package org.apache.commons.math3.fraction;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math3.FieldElement;
import org.apache.commons.math3.exception.MathArithmeticException;
import org.apache.commons.math3.exception.NullArgumentException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.ArithmeticUtils;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for {@link org.apache.commons.math3.fraction.Fraction#percentageValue()}.
 */
public class Fraction_percentageValue_TriageGen2Test {

    @Test
    public void testPercentageValue_Zero() {
        Fraction fraction = new Fraction(0, 1);
        double expected = 0.0;
        double actual = fraction.percentageValue();
        Assert.assertEquals("percentageValue() should return 0.0 for a fraction of 0", expected, actual, 1e-10);
    }

    @Test
    public void testPercentageValue_Half() {
        Fraction fraction = new Fraction(1, 2);
        double expected = 50.0;
        double actual = fraction.percentageValue();
        Assert.assertEquals("percentageValue() should return 50.0 for a fraction of 1/2", expected, actual, 1e-10);
    }

    @Test
    public void testPercentageValue_One() {
        Fraction fraction = new Fraction(1, 1);
        double expected = 100.0;
        double actual = fraction.percentageValue();
        Assert.assertEquals("percentageValue() should return 100.0 for a fraction of 1", expected, actual, 1e-10);
    }

    @Test
    public void testPercentageValue_Negative() {
        Fraction fraction = new Fraction(-1, 4);
        double expected = -25.0;
        double actual = fraction.percentageValue();
        Assert.assertEquals("percentageValue() should return -25.0 for a fraction of -1/4", expected, actual, 1e-10);
    }

    @Test
    public void testPercentageValue_LargeValue() {
        Fraction fraction = new Fraction(2, 1);
        double expected = 200.0;
        double actual = fraction.percentageValue();
        Assert.assertEquals("percentageValue() should return 200.0 for a fraction of 2", expected, actual, 1e-10);
    }

    @Test
    public void testPercentageValue_SmallValue() {
        Fraction fraction = new Fraction(1, 1000);
        double expected = 0.1;
        double actual = fraction.percentageValue();
        Assert.assertEquals("percentageValue() should return 0.1 for a fraction of 1/1000", expected, actual, 1e-10);
    }
}
